library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;
use std.env.all;
use work.pexport.all;
library candidate;

-- Authored cached code, CPU memory-port model, no BIOS/assets or physical PHY.
-- Instances and paired output declarations are generated by the runner.
entity tb_cpu_cache_contract is
    generic (SEED : natural := 1; PAUSES : boolean := false;
             EARLY_DONE : boolean := false; RESETS : boolean := false;
             TRACE : boolean := false; FILL_FAULT : boolean := false;
             EXPECTED_COUNT : positive := 20);
end entity;

architecture test of tb_cpu_cache_contract is
    type words is array(natural range <>) of std_logic_vector(31 downto 0);
    impure function load(path : string; size : positive; sparse : boolean) return words is
        file data : text open read_mode is path;
        variable row : line;
        variable result : words(0 to size-1) := (others=>(others=>'0'));
        variable address : std_logic_vector(31 downto 0);
        variable index : natural := 0;
    begin
        while not endfile(data) loop
            readline(data,row);
            if sparse then hread(row,address); index:=to_integer(unsigned(address))/4; end if;
            assert index<size report "Diagnostic image exceeds memory" severity failure;
            hread(row,result(index)); index:=index+1;
        end loop;
        return result;
    end function;
    constant rom : words(0 to 127) := load("rom.hex",128,false);
    constant ram_image : words(0 to 32767) := load("ram.hex",32768,true);
    constant expected : words(0 to EXPECTED_COUNT-1) := load("expected.hex",EXPECTED_COUNT,false);
    signal clk1x,clk2x,clk3x : std_logic := '1';
    signal reset,ss_reset : std_logic := '1';
    signal ce : std_logic := '1';
    signal dma_stall,irq,memory_pressure : std_logic := '0';
    signal done : std_logic := '0';
    signal ram_rnw : std_logic := '1';
    signal read_data,ram_data : std_logic_vector(31 downto 0) := (others=>'0');
    signal cache_wr,tagvalids : std_logic_vector(3 downto 0) := (others=>'0');
    signal cache_addr : std_logic_vector(7 downto 0) := (others=>'0');
    signal cache_data : std_logic_vector(31 downto 0) := (others=>'0');
    signal dma_cache_addr : std_logic_vector(20 downto 0) := (others=>'0');
    signal dma_cache_data : std_logic_vector(31 downto 0) := (others=>'0');
    signal dma_cache_write : std_logic := '0';
    signal probe_cop0,candidate_probe_cop0 : std_logic_vector(95 downto 0);
    signal probe_fetch,candidate_probe_fetch : unsigned(31 downto 0);
    signal probe_tag,candidate_probe_tag : std_logic_vector(23 downto 0);
    signal probe_accept,candidate_probe_accept,probe_invalidate,candidate_probe_invalidate : std_logic;
    signal checked_edges,retired,cached_retired,fill_count,fill_words,isolated_stores,irq_count : natural := 0;
    signal ce_pauses,memory_delay_cycles,fills_under_pressure : natural := 0;
    signal shadow_edges,shadow_address_changes,shadow_data_changes : natural := 0;
    signal restart_count : natural := 0;
    signal fill_start_mask : std_logic_vector(3 downto 0) := "0000";
    signal active_fill,memory_busy : std_logic := '0';
    signal aborted_fill_words : natural := 0;
    -- GENERATED_DECLARATIONS
begin
    clk1x <= not clk1x after 15 ns;
    clk2x <= not clk2x after 7500 ps;
    clk3x <= not clk3x after 5 ns;
    -- GENERATED_INSTANCES
    -- GENERATED_OBSERVER

    process
    begin
        for edge in 1 to 4 loop wait until falling_edge(clk1x); end loop;
        ss_reset<='0';
        for edge in 1 to 50 loop wait until falling_edge(clk1x); end loop;
        reset<='0';
        if RESETS then
            -- Warm-cache restart, then abort another in-flight fill. Cache RAM
            -- retains its contents across CPU reset, just like the reference.
            wait until cached_retired>=30;
            wait until falling_edge(clk1x); reset<='1'; ss_reset<='1';
            for edge in 1 to 4 loop wait until falling_edge(clk1x); end loop;
            ss_reset<='0';
            for edge in 1 to 50 loop wait until falling_edge(clk1x); end loop;
            reset<='0'; restart_count<=1;
            wait until active_fill='1';
            wait until cache_wr/="0000";
            wait until rising_edge(clk3x); -- first emitted word is consumed
            wait until falling_edge(clk3x); reset<='1'; ss_reset<='1';
            for edge in 1 to 4 loop wait until falling_edge(clk1x); end loop;
            ss_reset<='0';
            for edge in 1 to 50 loop wait until falling_edge(clk1x); end loop;
            reset<='0'; restart_count<=2;
        end if;
        wait;
    end process;

    process(clk1x)
        variable ticks : natural := 0;
        variable pause_remaining : natural := 0;
        variable shadow_addr : unsigned(31 downto 0) := (others=>'0');
        variable shadow_tag : std_logic_vector(23 downto 0) := (others=>'0');
    begin
        if falling_edge(clk1x) then
            shadow_addr:=probe_fetch; shadow_tag:=probe_tag;
        elsif rising_edge(clk1x) then
            ticks:=ticks+1; memory_pressure<='0';
            if reset='1' then ce<='1'; pause_remaining:=0;
            elsif PAUSES then
                -- psx_top updates CE on rising 1x and only enters a user/card
                -- pause while memory is idle, stallNext=0 and SS_idle=1.
                -- Arbitrary CE interruption of late data reads is outside
                -- that integration contract. DMA-like competing memory work
                -- stretches pending requests; dmaStallCPU is zero with the
                -- selected upstream TURBO_CACHE=0 configuration.
                if pause_remaining>0 then
                    ce<='0'; pause_remaining:=pause_remaining-1; ce_pauses<=ce_pauses+1;
                else
                    ce<='1';
                    if (ticks+SEED) mod 17=0 and SS_idle='1' and stallNext='0'
                        and memory_busy='0' and active_fill='0' and done='0' and memory_pressure='0' then
                        ce<='0'; pause_remaining:=2; ce_pauses<=ce_pauses+1;
                    end if;
                end if;
                if (ticks+SEED) mod 29<4 then memory_pressure<='1'; end if;
            end if;
            if probe_accept='1' then
                shadow_edges<=shadow_edges+1;
                if shadow_addr(11 downto 4)/=probe_fetch(11 downto 4) then
                    shadow_address_changes<=shadow_address_changes+1;
                end if;
                if shadow_tag/=probe_tag then shadow_data_changes<=shadow_data_changes+1; end if;
            end if;
        end if;
    end process;

    -- One owner for the response signals and modeled RAM. Fill writes run on
    -- 3x independently of CE; completion is held until an enabled 1x consumer.
    -- RAM fills start at the requested word and continue to the line end,
    -- matching memorymux's 1111/1110/1100/1000 valid masks, not an aligned fill.
    process(clk3x)
        variable ram : words(0 to 32767) := ram_image;
        variable pending,was_reset,fill,is_data : boolean := false;
        variable delay,word_index,start_word,transaction,checks : natural := 0;
        variable emitted_words : natural := 0;
        variable address,physical,line_base : unsigned(31 downto 0);
        variable value : std_logic_vector(31 downto 0);
        variable at_cpu_edge,completion_sent : boolean := false;
        variable irq_serviced : natural := 0;
    begin
        if rising_edge(clk3x) then
            at_cpu_edge:=clk1x='1' and clk1x'last_event=0 ns;
            cache_wr<="0000"; dma_cache_write<='0';
            if reset='1' then
                done<='0'; irq<='0'; active_fill<='0'; memory_busy<='0';
                if not was_reset then
                    if pending and active_fill='1' then aborted_fill_words<=emitted_words; end if;
                    ram:=ram_image; checks:=0; irq_serviced:=0;
                end if;
                pending:=false;
                was_reset:=true;
            else
                was_reset:=false;
                if at_cpu_edge and ce='1' then done<='0'; end if;
                if pending then
                    if delay>0 then
                        if memory_pressure='0' then delay:=delay-1;
                        else
                            memory_delay_cycles<=memory_delay_cycles+1;
                            if fill then fills_under_pressure<=fills_under_pressure+1; end if;
                        end if;
                    elsif fill then
                        physical:=line_base+word_index*4;
                        value:=ram(to_integer(physical)/4);
                        if FILL_FAULT and physical=x"00013000" then value:=value xor x"00000001"; end if;
                        cache_data<=value;
                        cache_addr<=std_logic_vector(address(11 downto 4));
                        cache_wr<=std_logic_vector(shift_left(to_unsigned(1,4),word_index));
                        fill_words<=fill_words+1;
                        emitted_words:=emitted_words+1;
                        if word_index=start_word then read_data<=value; ram_data<=value; end if;
                        if EARLY_DONE and word_index=start_word+1 and not completion_sent then
                            done<='1'; completion_sent:=true;
                        end if;
                        if word_index=3 then
                            -- Cache write above is consumed at the NEXT 3x
                            -- edge; defer ordinary completion until then.
                            fill:=false; delay:=0;
                        else word_index:=word_index+1; end if;
                    else
                        if not completion_sent then
                            physical:=address and x"1fffffff";
                            if physical>=x"1fc00000" and physical<x"1fc00200" then
                                value:=rom(to_integer(physical(8 downto 2)));
                            else
                                assert physical<ram'length*4 report "unexpected CPU read" severity failure;
                                value:=ram(to_integer(physical)/4);
                            end if;
                            read_data<=value; ram_data<=value; done<='1';
                        end if;
                        pending:=false; active_fill<='0'; memory_busy<='0';
                    end if;
                end if;
                if at_cpu_edge and ce='1' and request='1' then
                    assert not pending report "overlapping CPU reads" severity failure;
                    address:=addr_instr; is_data:=isdata='1';
                    if is_data then address:=addr_data; end if;
                    physical:=address and x"1fffffff";
                    transaction:=transaction+1;
                    if rnw='1' then
                        pending:=true; memory_busy<='1'; delay:=(transaction+SEED) mod 13+2;
                        completion_sent:=false; fill:=iscache='1' and not is_data;
                        emitted_words:=0;
                        if fill then
                            assert physical<ram'length*4 report "cached fetch outside RAM" severity failure;
                            active_fill<='1'; fill_count<=fill_count+1;
                            line_base:=physical and x"fffffff0";
                            start_word:=to_integer(address(3 downto 2)); word_index:=start_word;
                            fill_start_mask(start_word)<='1';
                            tagvalids<=std_logic_vector(shift_left(to_unsigned(15,4),start_word));
                        end if;
                    else
                        assert is_data and physical<ram'length*4 and mask="1111"
                            report "unexpected CPU write" severity failure;
                        ram(to_integer(physical)/4):=write_data;
                        if physical>=4096 and physical<4096+expected'length*4 then
                            assert to_integer((physical-4096)/4)=checks report "result stores reordered" severity failure;
                            assert write_data=expected(checks)
                                report "cache oracle mismatch index=" & natural'image(checks) &
                                    " got=" & to_hstring(write_data) & " expected=" & to_hstring(expected(checks))
                                severity failure;
                            checks:=checks+1;
                        elsif physical=x"0000ff04" then irq<='1';
                        elsif physical=x"0000ff08" then irq<='0'; irq_serviced:=irq_serviced+1; irq_count<=irq_count+1;
                        elsif physical=x"0000ff00" then
                            assert write_data=x"600df00d" and checks=expected'length and irq_serviced=1
                                report "cached CPU diagnostic incomplete" severity failure;
                            assert fill_start_mask="1111" and isolated_stores>0
                                report "cache fill/invalidation coverage missing" severity failure;
                            if PAUSES then
                                assert ce_pauses>0 and memory_delay_cycles>0 and fills_under_pressure>0
                                    report "cache pause coverage missing" severity failure;
                            end if;
                            if RESETS then
                                assert restart_count=2 and aborted_fill_words>0 and aborted_fill_words<4
                                    report "partial-fill reset coverage missing" severity failure;
                            end if;
                            report "PASS CPU cache seed=" & natural'image(SEED) & " checks=" & natural'image(checks) &
                                " edges=" & natural'image(checked_edges) & " retired=" & natural'image(retired) &
                                " fills=" & natural'image(fill_count) & " fillwords=" & natural'image(fill_words) &
                                " shadow_edges=" & natural'image(shadow_edges) &
                                " shadow_address_changes=" & natural'image(shadow_address_changes) &
                                " shadow_data_changes=" & natural'image(shadow_data_changes) &
                                " ce_pauses=" & natural'image(ce_pauses) & " memory_delay_cycles=" & natural'image(memory_delay_cycles) &
                                " fills_under_pressure=" & natural'image(fills_under_pressure) &
                                " resets=" & natural'image(restart_count) & " aborted_fill_words=" & natural'image(aborted_fill_words);
                            finish;
                        end if;
                    end if;
                end if;
                if at_cpu_edge and probe_invalidate='1' then
                    isolated_stores<=isolated_stores+1;
                end if;
            end if;
        end if;
    end process;
    process begin wait for 2 ms; assert false report "CPU cache execution timeout" severity failure; end process;
end architecture;
